async fn run_file_logger(
    path: PathBuf,
    mut rx: broadcast::Receiver<HarnessMessage>,
) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).await?;
    }

    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
